INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13246, 'koKR', 'Godne pożałowania, ale absolutnie konieczne.$b$bKirin Tor nie mógł sobie pozwolić, by znamienita czerwona smoczyca wpadła w ręce naszego największego wroga. Gdyby Malygos użył jej przeciwko nam w wojnie o Nexus, skutki byłyby druzgocące.$b$bŻałuję tylko, że nie mogliśmy jej zamiast tego ocalić.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13246, 'koKR', 'Gdybyśmy sądzili, że istnieje sposób, by ją odkupić, nie prosilibyśmy cię o odebranie jej życia.$b$bWiemy jednak, jak potężne stało się władanie Malygosa nad magią. Dzięki manipulacjom liniami mocy Azeroth nie ma sobie równych w sprawach tajemnych.', 0);
