INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(27362, 'koKR', '%s otwiera chaotyczną szczelinę!', '', 0),
(27363, 'koKR', '%s osłania się tarczą i kieruje swoją moc do szczelin!', '', 0),
(29593, 'koKR', '', 'Wiesz, co mówią o ciekawości...', 0),
(29594, 'koKR', '', 'Dam ci więcej, niż zdołasz udźwignąć!', 0),
(29595, 'koKR', '', 'Starczy mnie dla wszystkich.', 0),
(29596, 'koKR', '', 'Teraz dokończmy dzieła!', 0),
(29597, 'koKR', '', 'Do twarzy ci ze śmiercią.', 0),
(29598, 'koKR', '', 'Przeklęty... pech.', 0),
(29599, 'koKR', 'Chaos wzywa.', '', 0),
(29601, 'koKR', 'Rzeczywistość... rozpleciona.', '', 0),
(29602, 'koKR', 'Niezniszczalny.', '', 0),
(29604, 'koKR', 'Oczywiście.', '', 0),
(29605, 'koKR', 'Nieee!', '', 0),
(29608, 'koKR', 'Aaaach!', '', 0),
(29609, 'koKR', 'Precz!', '', 0),
(29610, 'koKR', 'Krwawcie!', '', 0),
(29627, 'koKR', 'Co? Gdzie, u licha... Nie stójcie tak, chłopaki, zabijcie kogoś!', '', 0),
(29628, 'koKR', 'No, teraz to do czegoś dochodzimy!', '', 0),
(29629, 'koKR', 'Czy to wszystko, co...', '', 0),
(66307, 'koKR', 'Oczywiście.', '', 0);
